const body = $('Webhook').first().json.body || {};
const data = $input.first().json;
const pantry = data.pantry || [];
const shoppingList = data.shopping || [];
const action = body.action || 'generate';
const family_size = body.family_size || 4;
const budget = body.budget || 'moderate';

// Store department mapping
const STORE_DEPARTMENTS = {
  produce: ['apple', 'banana', 'orange', 'lettuce', 'tomato', 'onion', 'potato', 'carrot', 'avocado', 'lime', 'cilantro', 'pepper', 'garlic', 'broccoli', 'spinach', 'cucumber'],
  meat: ['chicken', 'beef', 'pork', 'salmon', 'shrimp', 'turkey', 'sausage', 'bacon', 'fish'],
  dairy: ['milk', 'cheese', 'yogurt', 'butter', 'cream', 'eggs', 'sour cream'],
  bakery: ['bread', 'tortilla', 'buns', 'rolls', 'cake'],
  pantry: ['rice', 'pasta', 'beans', 'flour', 'sugar', 'oil', 'sauce', 'cereal', 'oats', 'quinoa'],
  frozen: ['ice cream', 'frozen', 'pizza'],
  beverages: ['water', 'juice', 'soda', 'coffee', 'tea'],
  snacks: ['chips', 'crackers', 'cookies', 'nuts', 'granola'],
  household: ['soap', 'detergent', 'paper', 'bags', 'wrap', 'foil']
};

function categorizeItem(name) {
  const lower = name.toLowerCase();
  for (const [dept, keywords] of Object.entries(STORE_DEPARTMENTS)) {
    if (keywords.some(k => lower.includes(k))) return dept;
  }
  return 'other';
}

// Identify low-stock and out-of-stock items
const lowStock = pantry.filter(i => (i.quantity || 0) <= 1);
const essentials = ['milk', 'eggs', 'bread', 'butter', 'rice', 'chicken', 'onion', 'garlic', 'oil', 'salt'];
const pantryNames = pantry.map(i => i.name?.toLowerCase() || '');
const missingEssentials = essentials.filter(e => !pantryNames.some(p => p.includes(e)));

// Combine all items to buy
const toBuy = new Map();

// Add existing shopping list items
shoppingList.forEach(item => {
  const name = item.name || item;
  toBuy.set(name.toLowerCase(), {
    name: name,
    quantity: item.quantity || 1,
    department: categorizeItem(name),
    source: 'shopping_list',
    priority: 'normal'
  });
});

// Add low-stock restocks
lowStock.forEach(item => {
  const key = (item.name || '').toLowerCase();
  if (!toBuy.has(key)) {
    toBuy.set(key, {
      name: item.name,
      quantity: 1,
      department: categorizeItem(item.name || ''),
      source: 'low_stock',
      priority: 'high'
    });
  }
});

// Add missing essentials
missingEssentials.forEach(name => {
  if (!toBuy.has(name)) {
    toBuy.set(name, {
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: 1,
      department: categorizeItem(name),
      source: 'essential',
      priority: 'high'
    });
  }
});

// Add any items from the request body
if (body.add_items && Array.isArray(body.add_items)) {
  body.add_items.forEach(item => {
    const name = typeof item === 'string' ? item : item.name;
    toBuy.set(name.toLowerCase(), {
      name: name,
      quantity: item.quantity || 1,
      department: categorizeItem(name),
      source: 'manual',
      priority: item.priority || 'normal'
    });
  });
}

const items = Array.from(toBuy.values());

// Group by store department for efficient shopping
const byDepartment = {};
items.forEach(item => {
  if (!byDepartment[item.department]) byDepartment[item.department] = [];
  byDepartment[item.department].push(item);
});

// Estimate cost (rough pricing)
const priceEstimates = {
  produce: 2.50, meat: 7.00, dairy: 3.50, bakery: 3.00,
  pantry: 3.00, frozen: 5.00, beverages: 3.00, snacks: 4.00,
  household: 5.00, other: 4.00
};
const estimatedTotal = items.reduce((sum, i) => sum + (priceEstimates[i.department] || 4.00) * (i.quantity || 1), 0);

return {
  json: {
    store: 'your store',
    total_items: items.length,
    estimated_cost: '$' + estimatedTotal.toFixed(2),
    family_size: family_size,
    by_department: byDepartment,
    all_items: items.sort((a, b) => a.department.localeCompare(b.department)),
    high_priority: items.filter(i => i.priority === 'high'),
    shopping_route: Object.keys(byDepartment).sort(),
    notes: [
      'Organized by store department for efficient shopping',
      `${items.filter(i => i.priority === 'high').length} high-priority items`,
      `Estimated total: $${estimatedTotal.toFixed(2)}`
    ]
  }
};
